S=$0;read Q;read T;read K||K=0;python3 -c 'import sys,json as j,os,zlib,base64 as B,re;q,T,k,s=sys.argv[1:];t=max(1,int(T));k="".join(c for c in k if c.isalnum())or"0";p=os.path;J=lambda x:j.dumps(x,separators=(",",":"));E=lambda b:sum((i+1)*(x+1)for i,x in enumerate(b))%10**18;w=re.findall(r"\w+",q.lower())or["light"];qn=" ".join(w);nt=E(J(w).encode());nl={"RAW":q,"NORM":qn,"TOK":w,"TM":"SCAN TOKEN GODEL ZETA CERT".split(),"AX":"finite closed deterministic".split(),"TRIV":[-2*(i+1)for i in range(min(3,len(w)))],"NTRIV":[.5,14.134725+nt%1000000/1000000]};sr=E(open(s,"rb").read())if p.exists(s)else 0;kv=E(k.encode());g=E(J([nl,t,k,"w4"]).encode());d=min(t,10);n=(2<<d)-1;m=997+g%97;Y=[(g+sr*i+i*i+kv)%m for i in range(n)];tz=sum(y%2<1 for y in Y);nz=n-tz;o=list(min((y,i)for i,y in enumerate(Y)));tt="Anselm %s V%s"%(" ".join(x.title()for x in w[:8]),k);wv=tt+".wav";os.system("ffmpeg -y -loglevel error -f lavfi -i sine=frequency=%s:duration=%s %r"%(110+(o[1]+kv)%220,t,wv));ab=open(wv,"rb").read()if p.exists(wv)else b"";bf=tt+".rmz85";en=B.b85encode(ab);open(bf,"wb").write(en);db=B.b85decode(en);open(wv,"wb").write(db);fc=int(db==ab and len(ab)>0 and p.getsize(wv)==len(ab));pf=int(o==list(min((y,i)for i,y in enumerate(Y))));G="C NL S O D T P M F E X L V H".split();C=[[G[0],qn],[G[1],nl],[G[2],sr],[G[3],sr],[G[4],1],[G[5],tz,nz],[G[6],o],[G[7],"synth"],[G[8],len(ab),zlib.crc32(ab)&0xffffffff],[G[9],bf],[G[10],wv],[G[11],tt],[G[12]],[G[13]]];con=int(tz+nz==n);comp=int([x[0]for x in C]==G);v=int(j.loads(J(C))==C and con and comp and pf and fc);D={"P":"RMZANS2K","TM":"RMZ-ANS-TM/4","NLTM":nl,"CODE":C,"K":k,"SELF":sr,"ORIGIN":sr,"D0":1,"ALL":n,"TZ":tz,"NZ":nz,"CON":con,"COMP":comp,"OPT":o,"OPTCERT":pf,"ENCODED":bf,"WAV":wv,"FILECERT":fc,"TITLE":tt,"MODE":"synth","V":v,"ANSCERT":v,"PCC":v,"ZE":v};ce=tt+".clcert";open(ce,"w").write(J(D)+"\n");print(J(D))' "$Q" "$T" "$K" "$S"